[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800;900&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

    :root {
      --black: #0d0d0d;
      --navy: #111827;
      --green: #55DA9B;
      --purple: #5620C1;
      --coral: #FF6B4A;
      --yellow: #FFD166;
      --white: #ffffff;
      --gray-100: #f9fafb;
      --gray-200: #f3f4f6;
      --gray-300: #e5e7eb;
      --gray-500: #6b7280;
      --gray-700: #374151;
      --gray-800: #1f2937;
      --font: 'Plus Jakarta Sans', sans-serif;
      --radius-sm: 8px;
      --radius-md: 14px;
      --radius-lg: 20px;
      --radius-xl: 28px;
    }

    html { scroll-behavior: smooth; }

    body {
      font-family: var(--font);
      color: var(--gray-800);
      background: var(--white);
      line-height: 1.6;
      overflow-x: hidden;
    }

    /* ── NAVBAR ── */
    .navbar {
      position: sticky;
      top: 0;
      z-index: 100;
      background: rgba(255,255,255,0.95);
      backdrop-filter: blur(12px);
      border-bottom: 1px solid var(--gray-200);
      padding: 0 24px;
    }
    .navbar-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      height: 64px;
      gap: 32px;
    }
    .logo {
      font-size: 22px;
      font-weight: 900;
      color: var(--black);
      text-decoration: none;
      letter-spacing: -0.5px;
      white-space: nowrap;
    }
    .logo span { color: var(--purple); }
    .nav-links {
      display: flex;
      gap: 24px;
      list-style: none;
      flex: 1;
    }
    .nav-links a {
      text-decoration: none;
      color: var(--gray-700);
      font-size: 15px;
      font-weight: 500;
      transition: color .2s;
    }
    .nav-links a:hover { color: var(--black); }
    .nav-actions {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-left: auto;
    }
    .btn-ghost {
      background: none;
      border: none;
      cursor: pointer;
      font-family: var(--font);
      font-size: 15px;
      font-weight: 600;
      color: var(--gray-700);
      padding: 8px 16px;
      border-radius: var(--radius-sm);
      transition: background .2s, color .2s;
    }
    .btn-ghost:hover { background: var(--gray-200); color: var(--black); }
    .btn-primary {
      background: var(--purple);
      color: var(--white);
      border: none;
      cursor: pointer;
      font-family: var(--font);
      font-size: 15px;
      font-weight: 700;
      padding: 9px 22px;
      border-radius: var(--radius-sm);
      transition: background .2s, transform .15s;
      white-space: nowrap;
    }
    .btn-primary:hover { background: #4515a3; transform: translateY(-1px); }

    /* ── HERO ── */
    .hero {
      background: var(--navy);
      color: var(--white);
      padding: 80px 24px 72px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }
    .hero::before {
      content: '';
      position: absolute;
      inset: 0;
      background:
        radial-gradient(ellipse 60% 50% at 20% 80%, rgba(86,32,193,0.35) 0%, transparent 70%),
        radial-gradient(ellipse 50% 60% at 80% 20%, rgba(85,218,155,0.2) 0%, transparent 70%),
        radial-gradient(ellipse 40% 40% at 50% 100%, rgba(255,107,74,0.15) 0%, transparent 70%);
      pointer-events: none;
    }
    .hero-content { position: relative; z-index: 1; max-width: 780px; margin: 0 auto; }
    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85,218,155,0.15);
      border: 1px solid rgba(85,218,155,0.4);
      color: var(--green);
      font-size: 13px;
      font-weight: 700;
      padding: 6px 14px;
      border-radius: 100px;
      margin-bottom: 28px;
      letter-spacing: 0.5px;
      text-transform: uppercase;
    }
    .hero h1 {
      font-size: clamp(36px, 5.5vw, 68px);
      font-weight: 900;
      line-height: 1.08;
      letter-spacing: -1.5px;
      margin-bottom: 20px;
    }
    .hero h1 em {
      font-style: normal;
      color: var(--green);
    }
    .hero-subtitle {
      font-size: clamp(18px, 2.5vw, 22px);
      font-weight: 600;
      color: rgba(255,255,255,0.75);
      margin-bottom: 40px;
    }
    .hero-ctas {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      margin-bottom: 18px;
    }
    .cta-google, .cta-email {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      width: 100%;
      max-width: 380px;
      padding: 16px 28px;
      border-radius: var(--radius-md);
      font-family: var(--font);
      font-size: 16px;
      font-weight: 700;
      cursor: pointer;
      transition: transform .2s, box-shadow .2s;
      border: none;
    }
    .cta-google {
      background: var(--white);
      color: var(--gray-800);
      box-shadow: 0 2px 12px rgba(0,0,0,0.15);
    }
    .cta-google:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(0,0,0,0.2); }
    .cta-email {
      background: var(--green);
      color: var(--black);
    }
    .cta-email:hover { transform: translateY(-2px); box-shadow: 0 6px 24px rgba(85,218,155,0.4); }
    .cta-google svg, .cta-email svg { width: 20px; height: 20px; flex-shrink: 0; }
    .hero-legal {
      font-size: 12px;
      color: rgba(255,255,255,0.45);
      max-width: 420px;
      margin: 0 auto 36px;
      line-height: 1.5;
    }
    .hero-legal a { color: rgba(255,255,255,0.65); text-decoration: underline; }

    /* Category pills */
    .category-pills-wrap {
      position: relative;
      z-index: 1;
      overflow: hidden;
    }
    .category-pills {
      display: flex;
      gap: 10px;
      overflow-x: auto;
      padding: 4px 2px 8px;
      scrollbar-width: none;
      justify-content: center;
      flex-wrap: wrap;
    }
    .category-pills::-webkit-scrollbar { display: none; }
    .pill {
      display: inline-flex;
      align-items: center;
      gap: 6px;
      background: rgba(255,255,255,0.1);
      border: 1px solid rgba(255,255,255,0.2);
      color: rgba(255,255,255,0.85);
      font-size: 13px;
      font-weight: 600;
      padding: 8px 16px;
      border-radius: 100px;
      cursor: pointer;
      white-space: nowrap;
      transition: background .2s, border-color .2s, color .2s;
      text-decoration: none;
    }
    .pill:hover {
      background: rgba(85,218,155,0.2);
      border-color: var(--green);
      color: var(--white);
    }

    /* ── FEATURES ── */
    .section { padding: 96px 24px; }
    .section-inner { max-width: 1280px; margin: 0 auto; }
    .section-label {
      font-size: 12px;
      font-weight: 800;
      letter-spacing: 2px;
      text-transform: uppercase;
      color: var(--purple);
      margin-bottom: 14px;
    }
    .section-title {
      font-size: clamp(28px, 3.5vw, 46px);
      font-weight: 900;
      letter-spacing: -1px;
      line-height: 1.1;
      color: var(--black);
      margin-bottom: 16px;
    }
    .section-subtitle {
      font-size: 17px;
      color: var(--gray-500);
      max-width: 560px;
      line-height: 1.7;
    }

    .features-section { background: var(--gray-100); }
    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
      gap: 24px;
      margin-top: 52px;
    }
    .feature-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      border: 1px solid var(--gray-200);
      transition: transform .25s, box-shadow .25s;
    }
    .feature-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
    .feature-icon {
      width: 52px;
      height: 52px;
      border-radius: var(--radius-sm);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 24px;
      margin-bottom: 20px;
    }
    .fi-green { background: rgba(85,218,155,0.15); }
    .fi-purple { background: rgba(86,32,193,0.12); }
    .fi-coral { background: rgba(255,107,74,0.12); }
    .fi-yellow { background: rgba(255,209,102,0.2); }
    .feature-card h3 {
      font-size: 18px;
      font-weight: 800;
      margin-bottom: 10px;
      color: var(--black);
    }
    .feature-card p { font-size: 15px; color: var(--gray-500); line-height: 1.6; }

    /* ── STATS ── */
    .stats-section {
      background: var(--black);
      padding: 80px 24px;
    }
    .stats-grid {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 40px;
      text-align: center;
    }
    .stat-item {}
    .stat-value {
      font-size: clamp(44px, 6vw, 72px);
      font-weight: 900;
      color: var(--green);
      letter-spacing: -2px;
      line-height: 1;
      margin-bottom: 10px;
    }
    .stat-label {
      font-size: 16px;
      font-weight: 600;
      color: rgba(255,255,255,0.6);
      letter-spacing: 0.5px;
    }

    /* ── COURSES ── */
    .courses-section { background: var(--white); }
    .tabs-wrap {
      overflow-x: auto;
      scrollbar-width: none;
      margin: 40px -8px 0;
      padding: 0 8px;
    }
    .tabs-wrap::-webkit-scrollbar { display: none; }
    .tabs {
      display: flex;
      gap: 6px;
      min-width: max-content;
      border-bottom: 2px solid var(--gray-200);
      padding-bottom: 0;
    }
    .tab {
      background: none;
      border: none;
      border-bottom: 2px solid transparent;
      margin-bottom: -2px;
      padding: 10px 18px;
      font-family: var(--font);
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-500);
      cursor: pointer;
      transition: color .2s, border-color .2s;
      white-space: nowrap;
    }
    .tab:hover { color: var(--gray-800); }
    .tab.active {
      color: var(--purple);
      border-bottom-color: var(--purple);
    }
    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
      gap: 24px;
      margin-top: 32px;
    }
    .course-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      border: 1px solid var(--gray-200);
      background: var(--white);
      transition: transform .25s, box-shadow .25s;
      cursor: pointer;
    }
    .course-card:hover { transform: translateY(-4px); box-shadow: 0 16px 48px rgba(0,0,0,0.1); }
    .course-thumb {
      width: 100%;
      aspect-ratio: 16/9;
      background: var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }
    .course-thumb-bg {
      position: absolute;
      inset: 0;
      background-size: cover;
      background-position: center;
      transition: transform .35s;
    }
    .course-card:hover .course-thumb-bg { transform: scale(1.04); }
    .course-thumb-label {
      position: absolute;
      bottom: 10px;
      left: 10px;
      background: rgba(0,0,0,0.7);
      color: var(--white);
      font-size: 12px;
      font-weight: 700;
      padding: 4px 10px;
      border-radius: 100px;
    }
    .course-body { padding: 18px 18px 20px; }
    .course-title {
      font-size: 15px;
      font-weight: 700;
      line-height: 1.4;
      color: var(--black);
      margin-bottom: 10px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }
    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 13px;
      color: var(--gray-500);
    }
    .course-instructor { font-weight: 600; color: var(--gray-700); }
    .course-stats { display: flex; gap: 12px; }
    .course-stat { display: flex; align-items: center; gap: 4px; }

    /* ── CREATIVE FEED ── */
    .feed-section { background: var(--gray-100); }
    .feed-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
      margin-top: 52px;
    }
    .feed-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 36px 30px;
      border: 1px solid var(--gray-200);
      transition: transform .25s, box-shadow .25s;
    }
    .feed-card:hover { transform: translateY(-4px); box-shadow: 0 12px 40px rgba(0,0,0,0.08); }
    .feed-num {
      font-size: 52px;
      font-weight: 900;
      line-height: 1;
      margin-bottom: 16px;
      letter-spacing: -2px;
    }
    .fn-green { color: var(--green); }
    .fn-purple { color: var(--purple); }
    .fn-coral { color: var(--coral); }
    .feed-card h3 {
      font-size: 20px;
      font-weight: 800;
      margin-bottom: 10px;
      color: var(--black);
    }
    .feed-card p { font-size: 15px; color: var(--gray-500); line-height: 1.65; }

    /* ── TEACHERS ── */
    .teachers-section { background: var(--white); }
    .teachers-header {
      display: flex;
      align-items: flex-end;
      justify-content: space-between;
      gap: 24px;
      flex-wrap: wrap;
      margin-bottom: 48px;
    }
    .teachers-carousel-wrap {
      position: relative;
    }
    .teachers-carousel {
      display: flex;
      gap: 20px;
      overflow-x: auto;
      scroll-snap-type: x mandatory;
      scrollbar-width: none;
      padding-bottom: 8px;
    }
    .teachers-carousel::-webkit-scrollbar { display: none; }
    .teacher-card {
      flex: 0 0 220px;
      scroll-snap-align: start;
      border-radius: var(--radius-lg);
      overflow: hidden;
      background: var(--gray-100);
      border: 1px solid var(--gray-200);
      transition: transform .25s, box-shadow .25s;
      cursor: pointer;
    }
    .teacher-card:hover { transform: translateY(-4px); box-shadow: 0 14px 40px rgba(0,0,0,0.1); }
    .teacher-avatar {
      width: 100%;
      aspect-ratio: 1;
      background: linear-gradient(135deg, #e0d7ff 0%, #c4f0de 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 52px;
      font-weight: 900;
      color: var(--purple);
      position: relative;
    }
    .teacher-avatar-inner {
      width: 80px;
      height: 80px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--purple) 0%, var(--green) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 28px;
      font-weight: 900;
      color: var(--white);
    }
    .teacher-info { padding: 16px 16px 20px; }
    .teacher-name {
      font-size: 16px;
      font-weight: 800;
      color: var(--black);
      margin-bottom: 4px;
    }
    .teacher-specialty {
      font-size: 13px;
      color: var(--gray-500);
      font-weight: 500;
    }
    .carousel-nav {
      display: flex;
      gap: 10px;
      margin-top: 24px;
      justify-content: center;
    }
    .carousel-btn {
      width: 44px;
      height: 44px;
      border-radius: 50%;
      border: 2px solid var(--gray-300);
      background: var(--white);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 18px;
      color: var(--gray-700);
      transition: background .2s, border-color .2s, color .2s;
    }
    .carousel-btn:hover {
      background: var(--purple);
      border-color: var(--purple);
      color: var(--white);
    }

    /* ── TESTIMONIALS ── */
    .testimonials-section { background: var(--gray-100); }
    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 24px;
      margin-top: 52px;
    }
    .testimonial-card {
      background: var(--white);
      border-radius: var(--radius-lg);
      padding: 32px 28px;
      border: 1px solid var(--gray-200);
      transition: transform .25s, box-shadow .25s;
    }
    .testimonial-card:hover { transform: translateY(-3px); box-shadow: 0 10px 32px rgba(0,0,0,0.07); }
    .stars { color: var(--yellow); font-size: 18px; margin-bottom: 14px; letter-spacing: 2px; }
    .testimonial-quote {
      font-size: 15px;
      line-height: 1.7;
      color: var(--gray-700);
      font-style: italic;
      margin-bottom: 20px;
    }
    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }
    .author-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 15px;
      font-weight: 800;
      color: var(--white);
      flex-shrink: 0;
    }
    .av-1 { background: linear-gradient(135deg, var(--purple), #8b5cf6); }
    .av-2 { background: linear-gradient(135deg, var(--coral), var(--yellow)); }
    .av-3 { background: linear-gradient(135deg, var(--green), #14b8a6); }
    .av-4 { background: linear-gradient(135deg, #f472b6, var(--coral)); }
    .author-name { font-size: 15px; font-weight: 700; color: var(--black); }
    .author-label { font-size: 12px; color: var(--gray-500); }

    /* ── TEAMS ── */
    .teams-section {
      background: linear-gradient(135deg, var(--navy) 0%, #1e1050 100%);
      padding: 96px 24px;
    }
    .teams-inner {
      max-width: 1280px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 80px;
      align-items: center;
    }
    .teams-text {}
    .teams-text .section-label { color: var(--green); }
    .teams-text .section-title { color: var(--white); }
    .teams-text .section-subtitle { color: rgba(255,255,255,0.6); margin-bottom: 36px; }
    .btn-learn {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: var(--green);
      color: var(--black);
      font-family: var(--font);
      font-size: 15px;
      font-weight: 700;
      padding: 14px 28px;
      border-radius: var(--radius-md);
      border: none;
      cursor: pointer;
      transition: background .2s, transform .2s;
      text-decoration: none;
    }
    .btn-learn:hover { background: #3ec989; transform: translateY(-2px); }
    .teams-visual {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 16px;
    }
    .teams-stat-card {
      background: rgba(255,255,255,0.07);
      border: 1px solid rgba(255,255,255,0.12);
      border-radius: var(--radius-lg);
      padding: 28px 24px;
      text-align: center;
    }
    .teams-stat-card .stat-value { font-size: clamp(32px, 3vw, 44px); margin-bottom: 6px; }
    .teams-stat-card .stat-label { font-size: 14px; }

    /* ── FAQ ── */
    .faq-section { background: var(--white); }
    .faq-list { max-width: 760px; margin: 52px auto 0; }
    .faq-item {
      border-bottom: 1px solid var(--gray-200);
    }
    .faq-question {
      width: 100%;
      background: none;
      border: none;
      text-align: left;
      padding: 22px 4px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 16px;
      cursor: pointer;
      font-family: var(--font);
      font-size: 17px;
      font-weight: 700;
      color: var(--black);
      transition: color .2s;
    }
    .faq-question:hover { color: var(--purple); }
    .faq-icon {
      width: 28px;
      height: 28px;
      border-radius: 50%;
      background: var(--gray-200);
      display: flex;
      align-items: center;
      justify-content: center;
      flex-shrink: 0;
      font-size: 18px;
      font-weight: 400;
      color: var(--gray-500);
      transition: background .2s, color .2s, transform .3s;
    }
    .faq-item.open .faq-icon {
      background: var(--purple);
      color: var(--white);
      transform: rotate(45deg);
    }
    .faq-answer {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.75;
      max-height: 0;
      overflow: hidden;
      transition: max-height .35s ease, padding .35s ease;
      padding: 0 4px;
    }
    .faq-item.open .faq-answer {
      max-height: 300px;
      padding: 0 4px 22px;
    }

    /* ── FOOTER ── */
    footer {
      background: var(--black);
      color: rgba(255,255,255,0.65);
      padding: 64px 24px 32px;
    }
    .footer-inner { max-width: 1280px; margin: 0 auto; }
    .footer-top {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 40px;
      padding-bottom: 52px;
      border-bottom: 1px solid rgba(255,255,255,0.1);
    }
